preConditionHook:
// Brooks's ii (insideBarCount 2) and iii (3). Containment is INCLUSIVE --
// p137, 'of the same size or smaller' -- so the FAILURE tests are strict and
// a bar that ties the prior high or low still counts as inside. That is the
// one difference from the catalog's InsideBar, which is strict.
allInside = true;
for (kk = 0; kk < (int)insideBarCount; ++kk) {
    if (el_gt(high[(int)lag + kk], high[(int)lag + kk + 1])) allInside = false;
    if (el_lt(low[(int)lag + kk], low[(int)lag + kk + 1])) allInside = false;
}
